mapper.select:
select id,title,pinned,active_run_id as activeRunId,created_at as createdAt from t_capp_ai_session
where user_id=#{userId}
and id < #{before}
order by id desc limit 21

mapper.delete:
delete from t_capp_ai_session where user_id=#{userId}
and id in
#{id}

delete from t_capp_ai_event where run_id in
(select id from t_capp_ai_run where user_id=#{userId} and session_id in
#{id}
)

delete from t_capp_ai_message where session_id in
(select id from t_capp_ai_session where user_id=#{userId} and id in
#{id}
)

mapper.select:
select id,session_id as sessionId,status,resume_id as resumeId,input_text as inputText,
       application_id as applicationId,task_type as action
from t_capp_ai_run where session_id=#{sessionId} and request_id=#{requestId} and user_id=#{userId}

mapper.insert:
insert into t_capp_ai_message(session_id,run_id,role,content,cards_json,created_at)
select #{sessionId},#{runId},#{role},#{content},#{cardsJson},current_timestamp(3)
from t_capp_ai_session where id=#{sessionId} and user_id=#{userId}

mapper.select:
select m.id,m.run_id as runId,m.role,m.content,m.cards_json as cardsJson,
       r.status as runStatus
from t_capp_ai_message m join t_capp_ai_session s on s.id=m.session_id
join t_capp_ai_run r on r.id=m.run_id
where s.id=#{sessionId} and s.user_id=#{userId}
and m.id < #{before}
order by m.id desc limit #{limit}

mapper.insert:
insert into t_capp_ai_event(run_id,event_type,data_json,created_at)
select id,#{type},#{data},current_timestamp(3) from t_capp_ai_run where id=#{runId} and user_id=#{userId}
and (status='RUNNING' or #{type} in ('done','cards'))
